import{_ as a}from"./chunks/ConsoleLauncher_Config.943Wsr3w.js";import{_ as t,o,c as s,ag as n}from"./chunks/framework.D9ghT4bC.js";const u=JSON.parse('{"title":"测试 AI 改动（Testing AI changes）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Developers/Testing-AI-changes.md","filePath":"zh/Developers/Testing-AI-changes.md"}'),r={name:"zh/Developers/Testing-AI-changes.md"};function i(c,e,p,d,h,l){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="测试-ai-改动-testing-ai-changes" tabindex="-1">测试 AI 改动（Testing AI changes） <a class="header-anchor" href="#测试-ai-改动-testing-ai-changes" aria-label="Permalink to &quot;测试 AI 改动（Testing AI changes）&quot;">​</a></h1><p>代码库支持运行自动化模拟，并为 AI 开发比较结果。</p><h2 id="启用" tabindex="-1">启用 <a class="header-anchor" href="#启用" aria-label="Permalink to &quot;启用&quot;">​</a></h2><p>设置一个自定义构建配置。</p><p>把工作目录设为 android/assets，就像运行桌面版时一样。并使用 <code>unciv.desktop.main</code> 模块。 <img src="'+a+'" alt="image"></p><h2 id="运行模拟" tabindex="-1">运行模拟 <a class="header-anchor" href="#运行模拟" aria-label="Permalink to &quot;运行模拟&quot;">​</a></h2><p>执行上面配置好的 ConsoleLauncher 构建配置。结果会出现在 IDE 的控制台中。</p><h2 id="配置模拟" tabindex="-1">配置模拟 <a class="header-anchor" href="#配置模拟" aria-label="Permalink to &quot;配置模拟&quot;">​</a></h2><p>在 <code>desktop\\src\\ConsoleLauncher.kt</code> 文件中，你可以调整要运行的模拟次数、使用哪些国家等。</p><p>建议使用没有 Unique 的通用文明。你可以看到代码向 <code>ruleset</code> 对象添加了一个通用 <code>Nation</code>，你可以用国家名常量作为控制开关，在代码各处控制不同的行为。</p><p>你还可以调整游戏参数和地图参数。为了获得更一致的结果，关闭自然奇观和野蛮人会有帮助。</p><p>默认情况下玩家顺序是随机的，这样更公平。</p><p><code>statTurns</code> 列表参数允许系统在特定回合保存某些统计数据，这样你可以在游戏过程中跟踪它们。</p><h2 id="理解结果" tabindex="-1">理解结果 <a class="header-anchor" href="#理解结果" aria-label="Permalink to &quot;理解结果&quot;">​</a></h2><p>默认情况下控制台会报告每个文明的胜利次数、胜利类型以及游戏结束时的 <code>popsum</code>。这是游戏结束时整个文明的平均人口数。</p><p>验证你对哪个文明会赢、会怎么赢的预期，以及报告数值的任何变化，是个好习惯。有些变化不会反映在胜率上，所以更适合在地图编辑器里做场景或用游戏内控制台来测试 AI 行为。</p><p>还会报告 p 值，根据胜率显示这个结果在二项检验中出现的可能性。如果这个值很小，说明这不太可能是随机出现的，你的改动对整体胜率产生了统计上显著的改变。运行 200-400 次模拟通常是一个不错的基准。</p>',17)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
